import paho.mqtt.client as mqtt

_client = None

def _publish(value):
    global _client
    if _client is None:
        broker = urlparse(os.environ.get('MQTT_BROKER_URL', 'mqtt://mosquitto:1883'))
        _client = mqtt.Client()
        _client.connect(broker.hostname, broker.port or 1883, 60)
