import asyncio
import json
import os
from datetime import datetime, timezone
from threading import Thread

from nats.aio.client import Client as NATS

async def _publish_async(value):
    client = NATS()
    await client.connect(servers=os.environ.get('NATS_URL', 'nats://nats:4222'))
    await client.publish(
        os.environ.get('NATS_OUTPUT_SUBJECT', 'demo.nats.mqtt.output'),
        json.dumps(value).encode('utf-8'),
    )
    await client.flush()
    await client.close()

def _publish(value):
    errors = []
    def run():
        try:
            asyncio.run(_publish_async(value))
        except Exception as error:
            errors.append(error)
    thread = Thread(target=run)
    thread.start()
    thread.join()
    if errors:
        raise errors[0]

